  // guidesDrawer
  'guidesDrawer.title': 'Self-Tape Guide',
  'guidesDrawer.subtitle': 'Check these before you hit REC.',
  'guidesDrawer.cameraTitle': 'Camera',
  'guidesDrawer.cameraTip1': 'Position the camera at eye level — not from below.',
  'guidesDrawer.cameraTip2': 'Use a tripod or a steady surface. Handheld shots make the focus drift in and out.',
  'guidesDrawer.cameraTip3': 'Shoot in 1080p or better. 4K is overkill for casting.',
  'guidesDrawer.cameraTip4': 'Turn OFF digital zoom — move the camera closer instead.',
  'guidesDrawer.audioTitle': 'Audio',
  'guidesDrawer.audioTip1': 'Record in a quiet room. Turn off AC, fridge, and notification sounds.',
  'guidesDrawer.audioTip2': 'Use an external microphone if you have one — a lavalier or shotgun mic gives 3x better sound.',
  'guidesDrawer.audioTip3': 'Test levels before recording. Your voice should sit between -12dB and -6dB.',
  'guidesDrawer.audioTip4': 'If you repeat a line, leave a 2-second pause before the next take.',
  'guidesDrawer.lightingTitle': 'Lighting',
  'guidesDrawer.lightingTip1': 'Face the window, don\'t turn away from it. Natural light is free and flattering.',
  'guidesDrawer.lightingTip2': 'Avoid backlighting (window behind you) — it darkens your face.',
  'guidesDrawer.lightingTip3': 'A single softbox placed in front and slightly above makes a great key light.',
  'guidesDrawer.lightingTip4': 'Check for harsh shadows under the eyes or on the neck.',
  'guidesDrawer.framingTitle': 'Framing',
  'guidesDrawer.framingTip1': 'Standard self-tape framing: mid-chest to just above the top of the head.',
  'guidesDrawer.framingTip2': 'Position the eyes about 1/3 down from the top edge.',
  'guidesDrawer.framingTip3': 'Keep your eyeline just beside the lens — NOT straight into it (unless the director asks for that).',
  'guidesDrawer.framingTip4': 'Use a neutral background — gray-blue or off-white. No posters or clutter.',
  'guidesDrawer.actingTitle': 'Acting',
  'guidesDrawer.actingTip1': 'Start with slating (name, height, agent) — brief and natural.',
  'guidesDrawer.actingTip2': 'Take one breath before you start. It gives natural timing.',
  'guidesDrawer.actingTip3': 'Play it FELT, not BIG. The camera sees everything — stay subtle.',
  'guidesDrawer.actingTip4': 'If you have an off-screen scene partner, ask them to speak quietly so you don\'t drown them out.',

