  'projCreate.worklog.culturalConsiderations': 'Cultural considerations for {culture}',
  'projCreate.worklog.specialCulturalNote': 'Special cultural considerations must be taken',
  'projCreate.cde.sikh.0': 'Chooda is a ceremony where the bride receives red bangles, and Haldi involves applying turmeric to the couple for purification and blessings.',
  'projCreate.cde.sikh.1': 'A music-filled celebration with dance and songs where the families prepare for the wedding with joy and traditional performances.',
  'projCreate.cde.sikh.2': 'Anand Karaj is the sacred Sikh wedding ceremony in the Gurdwara, followed by a reception with food and celebration.',
  'projCreate.cde.indisk.0': 'Ganesh Puja asks for blessings from Ganesha to remove obstacles, and Haldi is applied to the couple to cleanse and protect.',
  'projCreate.cde.indisk.1': 'Intricate henna is applied to the bride\'s hands and feet in complex patterns symbolizing joy, spiritual awakening and offerings.',
  'projCreate.cde.indisk.2': 'A lively celebration with traditional songs, dance and music where both families take part in performances and friendly competitions.',
  'projCreate.cde.indisk.3': 'The sacred Hindu wedding ceremony with the Saptapadi (seven steps) and Mangalsutra, followed by a feast and traditional rituals.',
  'projCreate.cde.pakistansk.0': 'A Mehndi celebration where the bride has henna applied while family and friends sing traditional Pakistani wedding songs with traditional music and dance.',
  'projCreate.cde.pakistansk.1': 'Baraat is the groom\'s arrival at the wedding, and Nikkah is the religious Islamic wedding ceremony with the signing of the nikah contract.',
  'projCreate.cde.pakistansk.2': 'Walima is the traditional reception hosted by the groom\'s family to celebrate the new marriage with food and joy.',
  'projCreate.cde.tyrkisk.0': 'A tradition-rich evening where the bride has henna applied to her hands while female guests sing wistful songs about leaving the childhood home.',
  'projCreate.cde.tyrkisk.1': 'The official wedding day with a civil or religious ceremony, followed by a large celebration with traditional Turkish food, music and dance.',
  'projCreate.cde.arabisk.0': 'The Islamic wedding ceremony where the nikah contract is signed in the presence of witnesses and family, often followed by duaa and prayers.',
  'projCreate.cde.arabisk.1': 'Zaffe is a spectacular procession with music and dance that leads the couple to the celebration, followed by the Walima reception.',
  'projCreate.cde.somalisk.0': 'The religious Islamic wedding with recitation of the Quran, the nikah contract and duaa in the presence of family and community.',
  'projCreate.cde.somalisk.1': 'A traditional Somali wedding celebration with authentic food, cultural dance, poetry and music celebrating the new marriage.',
  'projCreate.cde.etiopisk.0': 'A traditional Ethiopian pre-wedding ceremony with blessings, prayers and a family gathering before the official wedding.',
  'projCreate.cde.etiopisk.1': 'A grand celebration with a traditional Ethiopian coffee ceremony, injera food, cultural music and dance celebrating the new family.',
  'projCreate.cde.nigeriansk.0': 'A Western-style wedding in a church or ceremony venue with a white dress and traditional European wedding customs.',
  'projCreate.cde.nigeriansk.1': 'An authentic Nigerian cultural ceremony with traditional attire, rituals, food and music specific to the family\'s tribe or region.',
  'projCreate.cde.muslimsk.0': 'An intimate celebration where the bride and female guests have henna applied in beautiful patterns while singing traditional songs.',
  'projCreate.cde.muslimsk.1': 'Nikkah is the official Islamic wedding ceremony with the contract signing, followed by the Walima reception to celebrate the marriage.',
  'projCreate.cde.libanesisk.0': 'A lively celebration where the bride has henna applied by older female relatives while guests take part in traditional Lebanese music.',
  'projCreate.cde.libanesisk.1': 'A spectacular Zaffe entrance with drums and ululating, followed by a reception with authentic Lebanese food and traditional dabke dance.',
  'projCreate.cwt.sikh.0.tasks.0': 'Meet with the families to discuss the schedule',
  'projCreate.cwt.sikh.0.tasks.1': 'Scout the ceremony venue and lighting conditions',
  'projCreate.cwt.sikh.0.tasks.2': 'Plan photo moments for the Chooda ceremony',
  'projCreate.cwt.sikh.0.tasks.3': 'Coordinate with other photographers/videographers',
  'projCreate.cwt.sikh.0.tasks.4': 'Check traditional attire and colors for better image quality',
  'projCreate.cwt.sikh.0.cons.0': 'Haldi can turn clothes yellow - plan your gear accordingly',
  'projCreate.cwt.sikh.0.cons.1': 'Respect sacred moments - not all photography is permitted',
  'projCreate.cwt.sikh.0.cons.2': 'Women and men may have separate ceremonies',
  'projCreate.cwt.sikh.0.cons.3': 'The red Chooda bangles are very important - get close-ups',
  'projCreate.cwt.sikh.0.cons.4': 'Family traditions can vary - always ask first',
  'projCreate.cwt.sikh.0.time': 'Start early in the day, the ceremony can take 3-4 hours',
  'projCreate.cwt.sikh.0.contacts.0': 'The groom\'s family',
  'projCreate.cwt.sikh.0.contacts.1': 'Religious leader',
  'projCreate.cwt.sikh.0.contacts.2': 'Event coordinator',
  'projCreate.cwt.sikh.0.equip.0': '85mm lens for portraits',
  'projCreate.cwt.sikh.0.equip.1': 'Fast autofocus for movement',
