  'prodMedia.j003': 'This is what the client needs to keep track of',
  'prodMedia.j004': 'One place for choices, approvals and deliverables. No hidden workflow behind multiple panels.',
  'prodMedia.j005': 'No rooms are open for the client yet',
  'prodMedia.j006': 'The producer has not shared any rooms in the project room yet. When a room is opened for the client, it appears here automatically.',
  'prodMedia.j007': 'Ask the producer to open the rooms you need, for example brief, material, delivery or meetings.',
  'prodMedia.j008': 'Complete the brief',
  'prodMedia.j009': 'Mobile draft is saved automatically',
  'prodMedia.j010': 'One screen card with the most important things the producer needs to understand direction, deliverable and follow-up.',
  'prodMedia.j011': 'The brief is locked because the project is approved. Changes to goal, message, references and contact point must go through a new approval round.',
  'prodMedia.j012': 'The same structure the producer uses further in planning and delivery. The client describes the goal, the hook and the action directly here.',
  'prodMedia.j013': 'Upload references directly into the brief',
  'prodMedia.j014': 'Attach films, PDFs, images or other material here. The reference is saved in the project and can be used further in the project room.',
  'prodMedia.j015': 'Choose a reference file',
  'prodMedia.j016': 'The reference is saved as its own project resource and becomes available further in the Project room.',
