  'prodMedia.j020': 'Here you make concrete what proves the message and how the content should be distributed across surfaces.',
  'prodMedia.j021': 'Storyboard and inspirations',
  'prodMedia.j022': 'The client sees scenes and frames in a calm form, and can add inspirations and references directly to the right scene without cluttering the production editor.',
  'prodMedia.j023': 'The client gets an overview of which scenes are actually blocked in the storyboard and can point inspirations to the right place.',
  'prodMedia.j024': 'No storyboard scenes are linked to the project yet.',
