  'prodMedia.j031': 'No storyboard inspirations are registered yet.',
  'prodMedia.j032': 'Script and change suggestions',
  'prodMedia.j033': 'The client reads the script in a clear form and writes suggested changes as separate inputs. The original text is not overwritten directly in the client view.',
  'prodMedia.j034': 'No scenes are linked to the script foundation yet.',
  'prodMedia.j035': 'Suggest a change',
  'prodMedia.j036': 'Use this for rewrites, clarifications or suggestions for the scene, not for editing the script itself directly.',
  'prodMedia.j037': 'The change suggestions sit as separate items the team can follow up, without mixing client comments into the script structure itself.',
  'prodMedia.j038': 'No script suggestions are registered yet.',
  'prodMedia.j039': 'Shotlist overview',
  'prodMedia.j040': 'This is the client view of the shotlist: clear, calm and scene-oriented. It shows what should be covered, where and with whom, but not the internal production noise.',
  'prodMedia.j041': 'The overview is deliberately compressed to plan, scene, location, cast and description. That makes it fast to read in meetings and safe to send to the client without them having to interpret internal shot detailing.',
